UPDATE articulos a SET contenido=(SELECT string_agg(coalesce(v.texto,substring(a.contenido from v.inicio for v.largo)),'' ORDER BY v.orden) FROM (VALUES (0, 1, 71, NULL::text),(1,0,0,E'<thead><tr><th scope="col">Condición de aceptación del sistema o componente mecánico</th><th scope="col">Cumple</th><th scope="col">No cumple</th><th scope="col">N/A*</th></tr></thead>'),(2, 72, 7, NULL::text),(3, 200, 60, NULL::text),(4,0,0,E'<td colspan="3">'),(5, 264, 811, NULL::text)) v(orden,inicio,largo,texto)) WHERE a.id='da4a10ca-2339-5937-9db2-82b0a66aeee7' AND md5(a.contenido)='ad335c01393a4cd8509413b9f8c55d73' RETURNING a.id,md5(a.contenido) hash;